-	if (!/^\p{Lu}/u.test(content)) {
-		return undefined;
-	}
-
-	if (/^[\p{Lu}][\p{L}\p{N}/-]*(?: [\p{Lu}][\p{L}\p{N}/-]*)*$/u.test(content)) {
